-- Whole-row recovery effect; the original legacy grant requirement remains separate.
with settings as materialized(select $heal_recovery_spec${"row":{"id":22108,"created_at":"2024-04-20T06:32:51.706592+00:00","operations":[{"id":"8e91d541-cacb-46ed-820a-b2a1b5538f42","data":{"type":"FOCUS","spellId":4977,"castingSource":"RANGER"},"type":"giveSpell"},{"id":"4a5700ba-b678-53b5-8e4e-4a8fb9dbde93","data":{"value":"RANGER:::-:::PRIMAL:::ATTRIBUTE_WIS","variable":"CASTING_SOURCES"},"type":"defineCastingSource"},{"id":"04695e45-7d66-5e7c-b684-42d7e9f3f8d0","data":{"value":{"value":"T"},"variable":"SPELL_ATTACK"},"type":"adjValue"},{"id":"3526be96-f368-5466-8979-6aaa9f910d38","data":{"value":{"value":"T"},"variable":"SPELL_DC"},"type":"adjValue"},{"id":"2fc7cf29-1ae4-5810-9638-26c22494a5e8","data":{"value":"spells","variable":"PRIMARY_SHEET_TABS"},"type":"adjValue"}],"name":"Heal Companion","actions":null,"level":1,"rarity":"COMMON","prerequisites":["an animal companion"],"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You have a deep devotion to your animal companion that enables you to magically heal their wounds. You gain the [Heal Companion](link_spell_4977) warden spell and a focus pool of 1 Focus Point.","special":null,"type":"feat","meta_data":{"source":{"url":"https://2e.aonprd.com/Feats.aspx?ID=1764","book":"Advanced Player's Guide","page":"132"},"foundry":{"rules":[]},"deprecated":true},"traits":[1344],"content_source_id":14,"version":null,"uuid":7476666523704164,"availability":null},"sources":[{"id":1,"name":"Player Core","group":"pathfinder-core","user_id":null,"deprecated":null,"require_key":false,"is_published":true,"required_content_sources":[]},{"id":11,"name":"Core Rulebook","group":"legacy","user_id":null,"deprecated":null,"require_key":false,"is_published":true,"required_content_sources":[]},{"id":14,"name":"Advanced Player's Guide (in progress)","group":"legacy","user_id":null,"deprecated":null,"require_key":false,"is_published":true,"required_content_sources":[11]}],"dependencies":[{"table":"trait","row":{"id":1344,"name":"Ranger","uuid":4013391771147273,"content_source_id":1}},{"table":"spell","row":{"id":4977,"name":"Heal Companion","rank":1,"content_source_id":1}}]}$heal_recovery_spec$::jsonb as spec), aliases as materialized(select a.id,a.uuid,a.name,a.content_source_id from public.ability_block a
where a.id=22108 or a.uuid=7476666523704164
  or (a.content_source_id=14 and lower(pg_catalog.regexp_replace(coalesce(a.name,''),'^[[:space:]]+|[[:space:]]+$','','g'))='heal companion')
  or lower(pg_catalog.regexp_replace(coalesce(a.meta_data#>>'{source,url}',''),'^[[:space:]]+|[[:space:]]+$','','g'))='https://2e.aonprd.com/feats.aspx?id=1764'), pending as materialized(select u.id,u.type,u.ref_id,u.content_source_id,u.data->>'name' as name,u.status->>'state' as state
from public.content_update u cross join settings s
where upper(pg_catalog.regexp_replace(coalesce(u.status->>'state',''),'^[[:space:]]+|[[:space:]]+$','','g')) not in('APPROVED','REJECTED') and (
 (replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-') in('ability-block','feat') and (
   u.ref_id=22108 or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')='22108'
   or pg_catalog.regexp_replace(coalesce(u.data->>'uuid',''),'^[[:space:]]+|[[:space:]]+$','','g')='7476666523704164'
   or (lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))='heal companion' and
     (u.content_source_id=14 or exists(select 1 from jsonb_array_elements(jsonb_build_array(u.data->>'content_source_id',u.data->>'source_id',u.data#>>'{source,content_source_id}',u.data#>>'{source,source_id}',u.data#>>'{source,id}',u.data#>>'{meta_data,content_source_id}',u.data#>>'{meta_data,source,content_source_id}',u.data#>>'{meta_data,source,source_id}')) x where pg_catalog.regexp_replace(coalesce(x#>>'{}',''),'^[[:space:]]+|[[:space:]]+$','','g')='14')))
   or lower(pg_catalog.regexp_replace(coalesce(u.data#>>'{meta_data,source,url}',''),'^[[:space:]]+|[[:space:]]+$','','g'))='https://2e.aonprd.com/feats.aspx?id=1764'))
 or exists(select 1 from jsonb_array_elements(s.spec->'dependencies') p where replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-')=p->>'table' and
   (u.ref_id=(p#>>'{row,id}')::bigint or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')=p#>>'{row,id}'
    or pg_catalog.regexp_replace(coalesce(u.data->>'uuid',''),'^[[:space:]]+|[[:space:]]+$','','g')=p#>>'{row,uuid}'
    or (lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))=lower(pg_catalog.regexp_replace(coalesce(p#>>'{row,name}',''),'^[[:space:]]+|[[:space:]]+$','','g')) and
      (u.content_source_id=(p#>>'{row,content_source_id}')::bigint or exists(select 1 from jsonb_array_elements(jsonb_build_array(u.data->>'content_source_id',u.data->>'source_id',u.data#>>'{source,content_source_id}',u.data#>>'{source,source_id}',u.data#>>'{source,id}',u.data#>>'{meta_data,content_source_id}',u.data#>>'{meta_data,source,content_source_id}',u.data#>>'{meta_data,source,source_id}')) x where pg_catalog.regexp_replace(coalesce(x#>>'{}',''),'^[[:space:]]+|[[:space:]]+$','','g')=p#>>'{row,content_source_id}')))))
 or (replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-')='content-source' and exists(select 1 from jsonb_array_elements(s.spec->'sources') p where
   u.ref_id=(p->>'id')::bigint or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')=p->>'id' or lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))=lower(pg_catalog.regexp_replace(coalesce(p->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))))))
select 'legacy-heal-companion-recovery' as id,coalesce(
 (select count(*)=3 and coalesce(bool_and(jsonb_build_object('id',r.id,'name',r.name,'user_id',r.user_id,'deprecated',r.deprecated,'is_published',r.is_published,'require_key',r.require_key,'required_content_sources',r.required_content_sources,'group',r."group")=p),false)
from settings s cross join lateral jsonb_array_elements(s.spec->'sources') p left join public.content_source r on r.id=(p->>'id')::bigint)
 and (select exists(select 1 from public.trait t where jsonb_build_object('id',t.id,'name',t.name,'uuid',t.uuid,'content_source_id',t.content_source_id)=(select p->'row' from settings s cross join lateral jsonb_array_elements(s.spec->'dependencies') p where p->>'table'='trait'))
 and exists(select 1 from public.spell t where jsonb_build_object('id',t.id,'name',t.name,'rank',t.rank,'content_source_id',t.content_source_id)=(select p->'row' from settings s cross join lateral jsonb_array_elements(s.spec->'dependencies') p where p->>'table'='spell')))
 and not exists(select 1 from pending)
 and (select count(*) from aliases)=1
 and exists(select 1 from public.ability_block a cross join settings s where a.id=22108 and to_jsonb(a)-'updated_at'-'search_tsv'=s.spec->'row')
 and exists(select 1 from pg_catalog.pg_trigger t
    where t.tgrelid='public.ability_block'::regclass
      and t.tgname='ability_block_bump_source_updated_at'
      and t.tgfoid=pg_catalog.to_regprocedure('public.bump_content_source_updated_at()')
      and t.tgenabled='O' and t.tgtype=29 and not t.tgisinternal
      and t.tgqual is null and t.tgnargs=0)
 ,false) as passed;
